// print() emulation. Python's print writes str(obj) followed by '\n' to
// stdout; for a bytes object str() is its repr, and for an int it is the plain
// decimal spelling.

import { PyBytes } from './pybytes.mjs';

/** Python's str() for the value kinds this program prints. */
export function pyStr(value) {
  if (value instanceof PyBytes) return value.toString();
  if (typeof value === 'bigint') return value.toString(10);
  return String(value);
}

/** print(value) — one value, default separator and newline, to stdout. */
export function pyPrint(value) {
  process.stdout.write(`${pyStr(value)}\n`);
}

